  "deckLegal": true,
  "faq": [
   {
    "id": "Q435",
    "date": "2025.12.12更新",
    "q": "「元々の効果」とは何ですか？",
    "a": "そのカードに記載されている効果です。トリガーは失いません。"
   },
   {
    "id": "Q436",
    "date": "2023.06.28更新",
    "q": "「そのキャラクターの下にあるカード」とは何を指しますか？",
    "a": "そのキャラクタークターの下にある表向きのカードと裏向きのカードを指します。レイド状態のキャラクターの場合、そのキャラクターのレイド元のカードを指します。"
   },
   {
    "id": "Q437",
    "date": "2023.06.28更新",
    "q": "「このフィールドがあるかぎり」とはこのカードとは別の<“個性”消失弾>がある場合も満たされますか？",
    "a": "いいえ、満たされません。<“個性”消失弾>の【登場時】で選んだキャラクターは、その<“個性”消失弾>が場から無くなると、元々の効果を失わせる効果が無くなり、アクティブになるようになります。"
   },
   {
    "id": "Q438",
    "date": "2023.06.28更新",
    "q": "このカードの【登場時】の効果を受けて、元々の効果を全て失っているカードの【起動メイン】は、他のカードの効果で参照できますか？",
    "a": "いいえ、できません。"
   },
   {
    "id": "Q474",
    "date": "2023.07.12更新",
    "q": "このカードの【登場時】で、相手のレイド状態のキャラを選ぶとそのキャラはレイドを失い、そのキャラにレイドすることはできますか？",
    "a": "いいえ、できません。【レイド】は効果ではないため、このカードの効果によって失いません。"
   },
   {
    "id": "Q974",
    "date": "2024.05.24更新",
    "q": "「元々の効果を全て失わせる。」を受けたキャラは、自身や他のカードの効果によって既に得ていた効果を失いますか？<br><br>・自身の効果の例：CGH-1-059 ランスロット「【登場時】このキャラは、次の自分のターン開始時まで、BP+1000。」<br>・他のカードの効果の例：UA01BT/CGH-1-015ルルーシュ・ランペルージ「【登場時】自分の場のキャラを1枚まで選び、このターン中、「このキャラはBP2000以下のキャラにブロックされない。」を与える。」",
    "a": "いいえ、失いません。そのカードが元々持っている常時参照する効果は、有効になっていたとしても失います。<br>・常時参照する効果の例：UA01BT/CGH-1-054ギルバート・G・P・ギルフォード「【自分のターン中】自分のフロントLのキャラの数が相手のフロントLのキャラの数以上の場合、このキャラはBP+1000。」"
   },
   {
    "id": "Q2213",
    "date": "2026.07.24更新",
    "q": "【退場時】や「このキャラがレイドされた時」や「このキャラが自分の場から手札に戻った時」等の「場ではない場所で発動する効果」は「元々の効果を失う」効果を受けた場合、発動しますか？",
    "a": "それが元々持っている効果の場合、発動しません。<br>※それが『このターン中、「【退場時】○○」を得る』等の得た効果の場合は元々の効果ではないため、失われず発動します。"
   }
  ]
